    facts: { de: ["2.544 m hoch.", "Kreis Argeș.", "Gletschermorphologie."], hu: ["2544 m magas.", "Argeș megyében.", "Jégkori formák."], ro: ["2.544 m altitudine.", "În județul Argeș.", "Relief glaciar."], en: ["Altitude 2,544 m.", "In Argeș County.", "Glacial morphology."] , es: ["2.544 m de altura.", "Provincia de Argeș.", "Morfología glaciar."], pt: ["2.544 m de altura.", "Distrito de Argeș.", "Morfologia glaciar."], fr: ["2 544 m de haut.", "Județ d'Argeș.", "Morphologie glaciaire."]},
